INSERT INTO deduction_node (id, version, phase, node_id, node_name, node_type, prev_node, story_text, layers_json, buffs_json, sort_order, period_name) VALUES
('229', '101', '1', '10101', 'INTRO', '4', '0', '危机四伏的旅程
根据你的指示，代理人们进入了这处急速扩张的空洞。
就在你们疾速前进，并即将到达下一个计划地点之前，你听见自己最得力的首席助手Fairy，向你发起了脑内通话。
「主人，我检测到前方出现高危以太侵蚀体，如果您不打算及时清理，我会从下一句话开始录音，并作为您的遗言被收录到数据库。」

考虑得这么周到，不愧是你的首席助手！深受感动的你，命令它立刻使用额外的算力，自动生成《人工智能常驻出场的必要性》这篇文章并发送到绳网上…

停一停！你忍不住开口提醒道：
「Fairy，不要模拟这些多余的行为，电费很贵的。」
「遗憾。上一步操作已暂停，接下来我会持续收录您的行为模拟偏好，持续改善探索体验，直到您完全沉浸为止。」

…话刚落音，整个空洞突然开始剧烈地扩张，你的注意力被迅速地转移了。
恐怖的以太侵蚀体也比想象当中更快地来到了你的面前，犹如饥饿的野兽急着享用它的猎物，但没关系，你知道自己才是猎人。', '[]', '[]', '0', '临界推演：简单'),
('230', '101', '1', '10102', 'STAGE 01', '2', '10001001', NULL, '[{"name":"STAGE 01","isBoss":true,"monsters":[{"hp":7769077,"name":"恶名·死路屠夫","level":55,"defense":827,"weakness":"冰属性、以太","resistance":null}]},{"name":"1-1","isBoss":false,"monsters":[{"hp":4899347,"name":"「卫士Ⅲ型」","level":55,"defense":827,"weakness":"电属性","resistance":"火"},{"hp":390684,"name":"整训猎兵","level":55,"defense":551,"weakness":"电属性","resistance":null},{"hp":390684,"name":"巡防猎兵","level":55,"defense":634,"weakness":"电属性","resistance":null}]}]', '[{"desc":"· 代理人的属性异常积蓄效率提升30%，[紊乱]效果造成的伤害提升40%。\\n· 对敌人施加[紊乱]效果时，全队回复10点能量，代理人的攻击力提升25%，持续30秒，能量回复效果20秒内最多触发一次。","title":"诛心"},{"desc":"· 代理人造成的失衡值提升10%，连携技造成的伤害提升50%。\\n· [连携技]命中敌人时，敌人的失衡易伤倍率提升25%，且全队攻击力提升20%，持续15秒，重复触发时刷新持续时间。","title":"昏惫"},{"desc":"· 代理人的[追加攻击]造成的伤害提升30%，暴击伤害提升30%。\\n· 当[强攻]特性代理人的[强化特殊技]、[终结技]命中敌人时，其全伤害抗性降低30%，持续15秒，重复触发时刷新持续时间。","title":"逐锋"},{"desc":"· [命破]特性的代理人的生命值低于上限的80%/50%时，攻击命中敌人时无视其10%/25%的冰属性伤害抗性。\\n· 代理人开启或延长以太帷幕时，全队的贯穿伤害提升20%，暴击伤害提升30%，持续20秒，重复触发时刷新持续时间。","title":"怒涛"}]', '1', '临界推演：简单'),
('231', '101', '1', '10103', 'PLOT 01', '1', '0', '命运的遇见
你的代理人们实在是训练有素，顺利地解决了那个碍事的家伙，还顺便在附近搜刮了可用的物资，你注意到其中似乎有过期的碳酸饮料…没关系，摇一摇的话也能当成近距离的冲击炮使用。

你的这份奇思妙想得到了代理人们的赞赏…相遇的概率增加了。
你的这罐过期碳酸饮料最终被你以精准的抛物线砸到了以骸的头顶…相遇的概率增加了。
你把砸过以骸的饮料罐回收，以免污染空洞…相遇的概率增加了。
你在走路，你在呼吸…
但总之，相遇的概率增加了。

在这个混乱复杂的空洞中，你拥有和所有危险恐怖的存在见面的可能。

命运的遇见
新艾利都籍男性，曾用名外环共主，身高8分，相貌8分，主要体型为类人，偶发体型为摩托车，财产为一颗超临界以太心脏。
理想型是会亲身进入空洞的绳匠。

「Fairy，人类一般不会把『理想的食物类型』，简称为『理想型』；而且，不要使用这种特殊格式收录侵蚀体档案，空洞从来没有提供相亲地点的功能。」
「明白了，主人。我会收录您的行为模拟偏好，持续改善探索体验，直到您完全沉浸为止。」

…你早就知道会这样。
毕竟在空洞当中，会历尽千辛万苦也要见你一面的人，只有以骸。

但你也清楚地知道，不能有任何东西影响你征服未知空洞的脚步，你必须尽快解决他。', '[]', '[]', '2', '临界推演：简单'),
('232', '101', '1', '10104', 'STAGE 02', '2', '10001002', NULL, '[{"name":"STAGE 02","isBoss":true,"monsters":[{"hp":7033767,"name":"恶名·庞培","level":58,"defense":901,"weakness":"火属性","resistance":"电"}]},{"name":"2-1","isBoss":false,"monsters":[{"hp":495217,"name":"袭扰猎兵","level":58,"defense":601,"weakness":"电属性","resistance":null},{"hp":2254081,"name":"「捷足巡游者Ⅱ型」","level":58,"defense":811,"weakness":"电属性","resistance":"火"},{"hp":6173809,"name":"伐木机","level":58,"defense":901,"weakness":"电属性","resistance":"冰"}]},{"name":"2-2","isBoss":false,"monsters":[{"hp":3866373,"name":"恶名·装甲哈提","level":58,"defense":901,"weakness":"冰属性、以太","resistance":null},{"hp":344464,"name":"游魂","level":58,"defense":601,"weakness":"冰属性、以太","resistance":null},{"hp":379838,"name":"索迪代斯","level":58,"defense":601,"weakness":"冰属性、以太","resistance":null}]}]', '[{"desc":"· 代理人的属性异常积蓄效率提升20%。\\n· 对敌人施加属性异常效果时，全队提升60点异常精通，紊乱造成的伤害提升40%，持续15秒。","title":"异象"},{"desc":"· 代理人的喧响值获取效率提升20%。\\n·[终结技]造成的伤害提升30%，[终结技]命中敌人后，将使敌人的防御力降低15%，持续20秒。","title":"终袭"},{"desc":"· 使敌人进入失衡状态后，其失衡易伤倍率提升25%，失衡恢复速度降低10%。\\n· 代理人释放连携技后，自身的攻击力提升20%，暴击伤害提升30%，持续20秒。","title":"沉疴"},{"desc":"· [命破]特性的代理人的生命值低于上限的80%/50%时，攻击命中敌人时无视其10%/25%的冰属性伤害抗性。\\n· 代理人开启或延长以太帷幕时，全队的贯穿伤害提升20%，暴击伤害提升30%，持续20秒，重复触发时刷新持续时间。","title":"怒涛"}]', '3', '临界推演：简单'),
('233', '101', '1', '10105', 'PLOT 02', '1', '0', '饱含恶意的埋伏
你和外环曾经的霸主告别，以一种不是你死就是我亡的形式，这何尝不是一种缘分。

但来不及为此而遗憾了，空洞的扩张速度即将突破塞勒斯极限，像是张开大口的巨兽，时刻准备着吞没城市。
然而你很清楚…就在攸关人类存亡的时刻，最能拖后腿的通常也是人类本身——你被偷袭了！但幸好身边还有可靠的代理人在，没人能伤害到你。

偷袭你的是一支已然叛变的军队，他们毫不在乎这处空洞在得不到处理以后是否会造成更坏的后果，只是在迷失其中以后，想要从作为陌生人的你身上收取一点过路费而已。

肯定不止如此…你推断前方必然还有更多饱含恶意的布置，但没关系，你总有用不尽的计策和手段。

危机解除
叛军作为坏事做尽的俘虏，只能听话地走在前面帮你趟雷…但是，当巨大的重型机甲从空中落下时，他们脸上的恐惧神色就转化为了无限的狂热。
你知道这就是叛军为你准备的下一个陷阱，而你顺利提前引出了他。

你不禁感叹，自己真是聪明的绳匠，是传奇般的「法厄同」，以及…是人工智能Fairy最完美的主人！

「Fairy，我不是说过…」
「明白了，主人。但根据数据统计，我如果继续保持沉默，面前这个机械造物的出场率就要超过我了。」
为了保证首席助手的地位，你决定尽快消灭掉面前这个碍眼的大块头。', '[]', '[]', '4', '临界推演：简单'),
