":635,"weakness":"火属性、以太","resistance":null}]},{"name":"4-4","isBoss":false,"monsters":[{"hp":952168,"name":"秽息残兵·盾卫","level":70,"defense":730,"weakness":"物理、火属性","resistance":null},{"hp":952168,"name":"秽息残兵·炮手","level":70,"defense":635,"weakness":"物理、火属性","resistance":null},{"hp":12393008,"name":"秽蚀·多佩冈亚·「变节者」","level":70,"defense":953,"weakness":"物理、火属性","resistance":"以太"}]},{"name":"4-4","isBoss":false,"monsters":[{"hp":3116664,"name":"魁梧施虐者","level":70,"defense":794,"weakness":"物理、风属性","resistance":null},{"hp":14909964,"name":"秽蚀·简","level":70,"defense":953,"weakness":"物理、风属性","resistance":"以太"}]},{"name":"4-4","isBoss":false,"monsters":[{"hp":10283030,"name":"骇鸟","level":70,"defense":953,"weakness":"电属性","resistance":"冰"},{"hp":1142506,"name":"秽息原牲","level":70,"defense":635,"weakness":"电属性","resistance":null}]},{"name":"4-2","isBoss":false,"monsters":[{"hp":895388,"name":"整训猎兵","level":70,"defense":635,"weakness":"物理、电属性","resistance":null},{"hp":984731,"name":"轰击猎兵","level":70,"defense":635,"weakness":"物理、电属性","resistance":null},{"hp":16899556,"name":"牲鬼·凶魁愚者","level":70,"defense":953,"weakness":"物理、电属性","resistance":"以太"}]},{"name":"4-3","isBoss":false,"monsters":[{"hp":716311,"name":"恶毒打手","level":70,"defense":635,"weakness":"冰属性、以太","resistance":null},{"hp":716311,"name":"贪婪射手","level":70,"defense":635,"weakness":"冰属性、以太","resistance":null},{"hp":10720138,"name":"帕里库斯","level":70,"defense":953,"weakness":"冰属性、以太","resistance":null}]},{"name":"4-2","isBoss":false,"monsters":[{"hp":19537462,"name":"秽息蚀者·阿瓦鲁斯","level":70,"defense":953,"weakness":"火属性、以太","resistance":"冰"},{"hp":1298411,"name":"颂礼赞者","level":70,"defense":635,"weakness":"火属性、以太","resistance":null}]}]', '[{"desc":"· 代理人的属性异常积蓄效率提升30%，[紊乱]效果造成的伤害提升40%。\\n· 对敌人施加[紊乱]效果时，全队回复10点能量，代理人的攻击力提升25%，持续30秒，能量回复效果20秒内最多触发一次。","title":"诛心"},{"desc":"· 代理人造成的失衡值提升10%，连携技造成的伤害提升50%。\\n· [连携技]命中敌人时，敌人的失衡易伤倍率提升25%，且全队攻击力提升20%，持续15秒，重复触发时刷新持续时间。","title":"昏惫"},{"desc":"· 队伍内存在1名/2名[强攻]特性的代理人时，全队造成的伤害提升20%/40%。\\n· 触发暴击后，代理人的电属性伤害提升30%，[强攻]特性代理人的暴击伤害额外提升40%，持续5秒，重复触发时刷新持续时间。","title":"倏袭"},{"desc":"· [命破]特性的代理人的生命值低于上限的80%/50%时，攻击命中敌人时无视其10%/25%的冰属性伤害抗性。\\n· 代理人开启或延长以太帷幕时，全队的贯穿伤害提升20%，暴击伤害提升30%，持续20秒，重复触发时刷新持续时间。","title":"怒涛"},{"desc":"· 代理人的[闪避反击]、[强化特殊技]造成的伤害提升30%。\\n· 代理人命中非失衡状态敌人时，造成的失衡值提升10%；命中失衡状态中的敌人时，暴击伤害提升30%，敌人的失衡易伤倍率提升25%。","title":"崩倾"},{"desc":"· 代理人的喧响值获取效率提升20%。\\n·[终结技]和[强化特殊技]命中敌人时，无视其20%的伤害抗性，[终结技]命中敌人后，代理人的[终结技]和[强化特殊技]造成的伤害提升50%，持续30秒，重复触发时刷新持续时间。","title":"奏鸣"},{"desc":"· 代理人造成的伤害提升20%，造成的物理属性伤害额外提升20%。\\n· 使敌人进入属性异常后，敌人的防御力降低10%，持续10秒；对敌人施加[紊乱]效果后，敌人的防御力额外降低25%，持续10秒，两个效果独立刷新持续时间。","title":"奇巧"},{"desc":"· 代理人的属性异常积蓄效率提升20%。\\n· 对敌人施加属性异常效果时，全队提升60点异常精通，紊乱造成的伤害提升40%，持续15秒。","title":"异象"},{"desc":"· 代理人的[追加攻击]造成的伤害提升30%，暴击伤害提升30%。\\n· 当[强攻]特性代理人的[强化特殊技]、[终结技]命中敌人时，其全伤害抗性降低30%，持续15秒，重复触发时刷新持续时间。","title":"逐锋"},{"desc":"· 代理人的生命值上限提升20%，[终结技]造成的伤害提升40%。\\n· 代理人发动[强化特殊技]后，能量和闪能获得效率提升20%，以太属性伤害提升35%，持续20秒，重复触发刷新持续时间。","title":"聚元"}]', '7', '临界推演：歧路回响'),
